import{_ as t,o as a,c as s,ag as i}from"./chunks/framework.DaCm-iTo.js";const g=JSON.parse('{"title":"CoreLib Actions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/storage/corelib-actions.md","filePath":"en/modules/storage/corelib-actions.md","lastUpdated":null}'),o={name:"en/modules/storage/corelib-actions.md"};function d(r,e,l,n,c,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="corelib-actions" tabindex="-1">CoreLib Actions <a class="header-anchor" href="#corelib-actions" aria-label="Permalink to &quot;CoreLib Actions&quot;">​</a></h1><p>When EmakiStorage is enabled, it adds five warehouse stages to the CoreLib action registry. Use them in other modules&#39; rewards, triggers, or pipeline templates to store and withdraw items, grant slots, or adjust stack ceilings.</p><blockquote><p>This page documents only the stages registered by EmakiStorage. CoreLib built-in stages are documented in <a href="./../corelib/actions.html">CoreLib Actions</a>. The old hyphenated <code>storage-deposit</code> is now written <code>storage_deposit</code>, and the others follow the same rule.</p></blockquote><p>All five stages use the category <code>storage</code> and declare <code>REQUIRED_ENTITY</code>; non-player targets are skipped. Which player is affected comes from the source, so there is no <code>target</code> parameter: use <code>self</code> for the caster, or <code>player_by_name</code> for a named player.</p><h2 id="stage-overview" tabindex="-1">Stage overview <a class="header-anchor" href="#stage-overview" aria-label="Permalink to &quot;Stage overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage ID</th><th>Description</th></tr></thead><tbody><tr><td><code>storage_deposit</code></td><td>Stores items into the target player&#39;s warehouse.</td></tr><tr><td><code>storage_withdraw</code></td><td>Withdraws items from the target player&#39;s warehouse.</td></tr><tr><td><code>storage_grant_slot</code></td><td>Grants or reclaims granted slots.</td></tr><tr><td><code>storage_unlock_slot</code></td><td>Adds purchased slots without charging.</td></tr><tr><td><code>storage_set_stacklimit</code></td><td>Sets the player-level or per-entry stack ceiling.</td></tr></tbody></table><p>All five require the player&#39;s storage record to be loaded in memory; otherwise they fail with <code>MISSING_CONTEXT</code>.</p><p>The <code>item</code> parameter is an ItemSource token, not a pipeline item. This module addresses stored goods by definition rather than by whatever stack a pipeline happens to be carrying, so it does not read <code>CoreActionKeys.ITEM</code>.</p><h2 id="storage-deposit" tabindex="-1">storage_deposit <a class="header-anchor" href="#storage-deposit" aria-label="Permalink to &quot;storage_deposit&quot;">​</a></h2><p>Stores items into the warehouse without touching any inventory.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>item</code></td><td>STRING</td><td>Yes</td><td>—</td><td>CoreLib ItemSource token.</td></tr><tr><td><code>amount</code></td><td>INTEGER</td><td>No</td><td><code>1</code></td><td>Units to store; must be positive.</td></tr></tbody></table><p>On success the stage reports <code>stored</code>, the amount actually stored, which may be less than requested (a partial deposit).</p><p>Failure cases:</p><ul><li>Storage data or a required service is not ready (<code>MISSING_CONTEXT</code>).</li><li><code>item</code> cannot be parsed as an ItemSource (<code>INVALID_CONFIG</code>).</li><li><code>amount</code> is not positive (<code>INVALID_CONFIG</code>).</li><li>The transaction is refused (<code>REJECTED</code>), with <code>reason</code> in the result data. Common reasons: <code>filtered</code> (rejected by the deposit filter), <code>unique_rejected</code> (a uniquely marked item with <code>allow_unique_items: false</code>), <code>no_free_slot</code> (a new entry is needed but slots are full), <code>slot_full</code> (the stack ceiling is reached).</li></ul><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | storage_deposit item=diamond amount=64&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=Steve | storage_deposit item=emakiitem-forge_token amount=1&#39;</span></span></code></pre></div><h2 id="storage-withdraw" tabindex="-1">storage_withdraw <a class="header-anchor" href="#storage-withdraw" aria-label="Permalink to &quot;storage_withdraw&quot;">​</a></h2><p>Withdraws items from the warehouse and hands them to the player. Entries are located by full <code>ItemStack#equals</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>item</code></td><td>STRING</td><td>Yes</td><td>—</td><td>CoreLib ItemSource token.</td></tr><tr><td><code>amount</code></td><td>INTEGER</td><td>No</td><td><code>1</code></td><td>Units to withdraw; must be positive.</td></tr></tbody></table><p>On success the stage reports <code>withdrawn</code>, the amount actually withdrawn.</p><p>Failure cases:</p><ul><li>Storage data or the transaction service is not ready (<code>MISSING_CONTEXT</code>).</li><li><code>item</code> cannot be parsed (<code>INVALID_CONFIG</code>).</li><li><code>amount</code> is not positive (<code>INVALID_CONFIG</code>).</li><li>The transaction is refused (<code>REJECTED</code>), with <code>reason</code> in the result data. Common reasons: <code>entry_missing</code> (no such entry in the warehouse), <code>inventory_full</code> (the inventory could not take it and <code>overflow_on_withdraw: return</code> has already credited the remainder back).</li></ul><p>The order is debit first, then hand out. The reverse would create a duplication bug where delivery succeeds but the debit fails; in this order the worst case is that the player receives less than requested, and that remainder is credited back immediately.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | storage_withdraw item=diamond amount=16&#39;</span></span></code></pre></div><h2 id="storage-grant-slot" tabindex="-1">storage_grant_slot <a class="header-anchor" href="#storage-grant-slot" aria-label="Permalink to &quot;storage_grant_slot&quot;">​</a></h2><p>Adjusts the granted slot pool, for level, codex, and similar reward flows.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>amount</code></td><td>INTEGER</td><td>Yes</td><td>—</td><td>Slots to grant. Negative reclaims.</td></tr></tbody></table><p>On success the stage reports <code>granted_slots</code>, the new total. An <code>amount</code> of <code>0</code> fails with <code>INVALID_CONFIG</code>.</p><p>This stage records an <code>ADMIN_GIVE</code> log entry. Administrative entries are always logged, regardless of <code>logging.enabled</code> and <code>logging.sources</code>.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | storage_grant_slot amount=10&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=Steve | storage_grant_slot amount=-5&#39;</span></span></code></pre></div><h2 id="storage-unlock-slot" tabindex="-1">storage_unlock_slot <a class="header-anchor" href="#storage-unlock-slot" aria-label="Permalink to &quot;storage_unlock_slot&quot;">​</a></h2><p>Adds purchased slots without charging, for reward flows. Unlike <code>storage_grant_slot</code>, it grows the <code>purchasedSlots</code> pool, which shifts the starting point of per-slot pricing for later paid expansions.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>amount</code></td><td>INTEGER</td><td>Yes</td><td>—</td><td>Slots to unlock; must be positive.</td></tr></tbody></table><p>On success the stage reports <code>purchased_slots</code>. A non-positive <code>amount</code> fails with <code>INVALID_CONFIG</code>.</p><p>This stage records an <code>UNLOCK</code> log entry with the detail <code>cost=none</code>.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | storage_unlock_slot amount=5&#39;</span></span></code></pre></div><h2 id="storage-set-stacklimit" tabindex="-1">storage_set_stacklimit <a class="header-anchor" href="#storage-set-stacklimit" aria-label="Permalink to &quot;storage_set_stacklimit&quot;">​</a></h2><p>Sets the player-level or per-entry stack ceiling.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>limit</code></td><td>INTEGER</td><td>Yes</td><td>—</td><td>New ceiling; must be <code>&gt;= 0</code>. <code>0</code> inherits the next level up.</td></tr><tr><td><code>slot</code></td><td>INTEGER</td><td>No</td><td><code>-1</code></td><td>Logical slot index. <code>-1</code> (or any negative value) sets the player-level default.</td></tr></tbody></table><p>Result data keys:</p><table tabindex="0"><thead><tr><th>Case</th><th>Key</th><th>Description</th></tr></thead><tbody><tr><td><code>slot</code> negative</td><td><code>default_stack_limit</code></td><td>The new player-level ceiling.</td></tr><tr><td><code>slot</code> non-negative</td><td><code>slot</code></td><td>The slot index that was changed.</td></tr><tr><td><code>slot</code> non-negative</td><td><code>stack_limit</code></td><td>The new per-entry ceiling.</td></tr></tbody></table><p>Failure cases:</p><ul><li>Storage data is not loaded (<code>MISSING_CONTEXT</code>).</li><li><code>limit</code> is negative (<code>INVALID_CONFIG</code>).</li><li><code>slot</code> is non-negative but that slot holds no entry (<code>INVALID_CONFIG</code>, with <code>slot</code> in the result data).</li></ul><p><code>0</code> means different things at different levels: at the entry and player levels it inherits the level above, while at the config level <code>capacity.default_stack_limit</code> uses <code>0</code> for unlimited. The three-level inheritance rules are covered in <a href="./configuration.html">Configuration</a>.</p><p>This stage records an <code>ADMIN_SET</code> log entry, which is always logged.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | storage_set_stacklimit limit=100000&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | storage_set_stacklimit limit=5000 slot=3&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | storage_set_stacklimit limit=0&#39;</span></span></code></pre></div><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./configuration.html">Configuration</a>: <code>stackLimit</code> three-level inheritance, deposit filters, per-slot pricing.</li><li><a href="./api.html">API and Integration</a>: the code entry points for the same capabilities and the <code>StorageResult</code> states.</li></ul>`,47)])])}const u=t(o,[["render",d]]);export{g as __pageData,u as default};
